{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Diphenhydramine, a close lipophilic tertiary-amine analogue sharing the diphenylmethyl motif, has an absolute oral bioavailability of 42% in elderly subjects, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Trimipramine, a tricyclic tertiary amine with similar N-methyl-alkylamine character, shows an absolute oral bioavailability of 41.4%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Pethidine, a basic phenylpiperidine with moderate lipophilicity, has an oral bioavailability of about 52%, supporting high F for the query's basic amine/lipophilic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Dapoxetine, a lipophilic tertiary amine with phenyl and naphthyl ether groups, has an absolute oral bioavailability of 42%, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Milnacipran, an amide-containing basic drug, has an absolute oral bioavailability of 85±3%, demonstrating that amide/amine drugs can have high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Fenspiride, a basic phenethylpiperidine drug, has an absolute oral bioavailability of 90%, supporting high F for the query's basic amine and lipophilic features.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All directly relevant analogue measurements, including close lipophilic tertiary-amine drugs (diphenhydramine, trimipramine, pethidine, dapoxetine), report absolute oral bioavailability ≥40%, and several amide/amine drugs reach 85–90%. The query's lipophilic, non-acidic, basic amine structure is consistent with high F. The only sub-20 value is a prodrug metabolite availability and does not outweigh this consistent evidence.",
  "evidence_gaps": [
    "No direct experimental F measurement exists for the query molecule; all evidence is from analogues.",
    "The single sub-20 value (perindoprilat 19%) is an active-metabolite availability after prodrug dosing, not a parent-drug absolute F, limiting its relevance."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

